package art

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"net/url"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// settlePageSize is one page of the item walk per library (QueryItems is
// paginated by contract): far beyond any realistic page, small enough that
// the pass yields to ctx between pages.
const settlePageSize = 500

// missingArtPathPrefix is the settle-side copy of the missing-art prefix
// rule (artwork): a poster URL whose path lives under a known missing-art
// asset prefix is the upstream's "no art" placeholder — the settle never
// fetches one, and no fetch row for one can exist. Deliberately duplicated
// across the binary boundaries (design D9): the api walk and the shikimori
// write side carry their own copies, both pinned by the committed golden
// fixture internal/api/testdata/golden/missing_art.json.
const missingArtPathPrefix = "/assets/globals/missing"

// missingArtURL reports whether u's PATH carries the missing-art prefix —
// the prefix rule, not an exact-URL list. Document URLs are stored absolute
// (older rows may carry the raw relative payload path; url.Parse sees the
// same path either way).
func missingArtURL(u string) bool {
	parsed, err := url.Parse(u)
	if err != nil {
		return false
	}
	return strings.HasPrefix(parsed.Path, missingArtPathPrefix)
}

// Settle runs ONE settle+GC pass (artwork): the shared document walk covers
// every library's series rows AND its non-series items — films and TV alike
// — collecting each namespace poster URL. The settle half Acquires every
// non-placeholder URL (fetch-once: rows and the singleflight collapse
// repeats; a corrupt document simply contributes no URLs); the GC half
// reclaims on REFERENCE LOSS, never time — the referenced set is every
// stored override selection unioned with every live document poster URL
// (conservative: gate flips and chain reorders never delete; the fetch
// rows' own sha256 column is deliberately NOT a reference). A fetch row
// whose URL is in neither set is deleted together with its blob dir; the
// repair legs delete a row whose bytes file is missing and a bytes dir with
// no surviving reference. The boot run is this same pass, not a bulk path,
// and every leg yields to ctx. Store-level read failures abort the pass
// (the janitor logs them); per-URL acquire failures are logged and skipped —
// the failure cooldown bounds the retry economics.
func (s *Service) Settle(ctx context.Context) error {
	live, err := s.walkPosterURLs(ctx)
	if err != nil {
		return err
	}
	for _, u := range live {
		if ctx.Err() != nil {
			return ctx.Err()
		}
		if missingArtURL(u) {
			continue // a known placeholder: honestly absent, never fetched
		}
		if _, err := s.Acquire(ctx, u, KindPoster); err != nil {
			slog.Warn("art: settle acquire skipped", "error", err)
		}
	}
	return s.gc(ctx, live)
}

// walkPosterURLs reads every library's series and item documents into the
// distinct live poster-URL set — ONE walk shared by the settle and the GC
// halves. A corrupt document yields no URLs (tolerant, like every dynamic
// read); a store-level failure aborts the pass. Series and non-series items
// ride the same loop: the GC union must hold every kind-field URL.
func (s *Service) walkPosterURLs(ctx context.Context) ([]string, error) {
	libs, err := s.st.ListLibraries(ctx)
	if err != nil {
		return nil, fmt.Errorf("art: list libraries: %w", err)
	}
	seen := make(map[string]bool)
	var urls []string
	add := func(raw json.RawMessage) {
		for _, u := range posterURLs(raw) {
			if !seen[u] {
				seen[u] = true
				urls = append(urls, u)
			}
		}
	}
	for _, lib := range libs {
		if ctx.Err() != nil {
			return nil, ctx.Err()
		}
		series, err := s.st.QuerySeries(ctx, lib.ID, "")
		if err != nil {
			return nil, fmt.Errorf("art: query series %d: %w", lib.ID, err)
		}
		for _, sr := range series {
			add(sr.Document)
		}
		for offset := 0; ; offset += settlePageSize {
			if ctx.Err() != nil {
				return nil, ctx.Err()
			}
			page, err := s.st.QueryItems(ctx, lib.ID, "", settlePageSize, offset)
			if err != nil {
				return nil, fmt.Errorf("art: query items %d: %w", lib.ID, err)
			}
			for _, it := range page {
				add(it.Document)
			}
			if len(page) < settlePageSize {
				break
			}
		}
	}
	return urls, nil
}

// posterURLs collects a document's namespace poster URLs — every
// sources.<ns>.poster string field, namespace order sorted so the walk is
// deterministic. A corrupt document yields nil.
func posterURLs(raw json.RawMessage) []string {
	var doc struct {
		Sources map[string]struct {
			Poster string `json:"poster"`
		} `json:"sources"`
	}
	if err := json.Unmarshal(raw, &doc); err != nil {
		return nil
	}
	names := make([]string, 0, len(doc.Sources))
	for name := range doc.Sources {
		names = append(names, name)
	}
	sort.Strings(names)
	out := make([]string, 0, len(names))
	for _, name := range names {
		if u := doc.Sources[name].Poster; u != "" {
			out = append(out, u)
		}
	}
	return out
}

// gc reconciles the fetch rows and the blob tree against the reference
// union — the override selections (a parseable art_ token protects its dir;
// src:/thumb selections resolve at read time and protect nothing on disk)
// plus the live document URLs, each hashed with the row kinds in play so a
// surviving URL keeps exactly the rows minted from it.
func (s *Service) gc(ctx context.Context, live []string) error {
	_, _, selections, err := s.st.ListArtOverrides(ctx)
	if err != nil {
		return fmt.Errorf("art: list overrides: %w", err)
	}
	overrideShas := make(map[string]bool)
	for _, sel := range selections {
		if sha, ok := tokenSHA(sel); ok {
			overrideShas[sha] = true
		}
	}
	hashes, shas, kinds, err := s.st.ListArtFetches(ctx)
	if err != nil {
		return fmt.Errorf("art: list fetches: %w", err)
	}
	rowKinds := make(map[string]bool, len(kinds))
	for _, kind := range kinds {
		rowKinds[kind] = true
	}
	refHash := make(map[string]bool, len(live)*len(rowKinds))
	for _, u := range live {
		for kind := range rowKinds {
			refHash[urlHash(u, kind)] = true
		}
	}
	keptShas := make(map[string]bool, len(hashes)+len(overrideShas))
	for i, h := range hashes {
		switch {
		case !refHash[h]:
			// Reference loss: the row dies together with its sha-dir
			// (unless a surviving row or override shares the content
			// address — the dir sweep below keeps it then).
			if err := s.st.DeleteArtFetch(ctx, h); err != nil {
				return fmt.Errorf("art: delete fetch %s: %w", h, err)
			}
		case !s.blobExists(shas[i]):
			// Repair leg: a referenced row whose bytes file is missing is
			// dropped, so the next encounter re-fetches instead of
			// trusting a ghost cache hit.
			if err := s.st.DeleteArtFetch(ctx, h); err != nil {
				return fmt.Errorf("art: delete fetch %s: %w", h, err)
			}
		default:
			keptShas[shas[i]] = true
		}
	}
	for sha := range overrideShas {
		keptShas[sha] = true
	}
	// Repair leg: a bytes dir with no surviving row and no override is
	// unreferenced on disk. Uploads carry no row at all — they survive on
	// their override alone and are swept exactly when that goes.
	dirs, err := os.ReadDir(s.dir)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil // nothing was ever stored
		}
		return fmt.Errorf("art: read blob tree: %w", err)
	}
	for _, d := range dirs {
		if !d.IsDir() || keptShas[d.Name()] {
			continue
		}
		if err := os.RemoveAll(filepath.Join(s.dir, d.Name())); err != nil {
			slog.Warn("art: gc remove failed", "dir", d.Name(), "error", err)
			continue
		}
		slog.Info("art: reclaimed unreferenced blob dir", "sha256", d.Name())
	}
	return nil
}
